/**
 * Biome map art: texture keys, loader and animation registration.
 * PNGs are generated by scripts/assets/gen-biomes.mjs (see docs/MAPS.md).
 * MapManager falls back to plain graphics for any key that failed to load.
 */
import { BIOMES, MAP_ART, HAZARD_DEFS, OBSTACLE_DEFS, BIOME_MECHANICS } from '../../data/biomes.js';
import { getAssetPath } from '../../utils/assetBase.js';
import { spaceAssetManifest } from '../../systems/spaceBackground.js';

export const BG_DIR = 'assets/backgrounds/biomes';
export const MAP_DIR = 'assets/sprites/map';

export const biomeBgKey = (biomeId, layer) => `biome-${biomeId}-${layer}`;
export const borderKey = (biomeId) => `map-border-${biomeId}`;
export const obstacleKey = (type) => `map-obs-${type}`;
export const hazardKey = (type) => `map-haz-${type}`;
export const hazardAnimKey = (type) => `map-haz-${type}-loop`;
export const zoneKey = (mechanic) => `map-zone-${mechanic}`;
export const zoneAnimKey = (mechanic) => `map-zone-${mechanic}-loop`;
export const CRATE_KEY = 'map-crate';
/** Animated teleporter portals (scripts/assets/gen-items.mjs): pair A cyan, pair B magenta. */
export const PORTAL_SIDES = ['a', 'b'];
export const PORTAL_ART = { size: 128, frames: 8, frameRate: 12 };
export const portalKey = (side) => `map-portal-${side}`;
export const portalAnimKey = (side) => `map-portal-${side}-loop`;

/**
 * Pure manifest of every map asset (key, relative path, kind, frame size). Used by the loader and tests.
 * @returns {Array<{key:string,path:string,kind:'image'|'sheet',frameWidth?:number,frameHeight?:number,frames?:number}>}
 */
export function biomeAssetManifest() {
  const out = [];
  Object.values(BIOMES).forEach((b) => {
    ['far', 'near'].forEach((layer) => out.push({ key: biomeBgKey(b.id, layer), path: `${BG_DIR}/${b.id}-${layer}.png`, kind: 'image', width: MAP_ART.bgSize, height: MAP_ART.bgSize }));
    out.push({ key: borderKey(b.id), path: `${MAP_DIR}/border-${b.id}.png`, kind: 'image', width: MAP_ART.borderSize, height: MAP_ART.borderSize });
  });
  Object.keys(OBSTACLE_DEFS).forEach((t) => out.push({ key: obstacleKey(t), path: `${MAP_DIR}/obstacle-${t}.png`, kind: 'image', width: MAP_ART.obstacleSize, height: MAP_ART.obstacleSize }));
  Object.keys(HAZARD_DEFS).forEach((t) => out.push({
    key: hazardKey(t), path: `${MAP_DIR}/hazard-${t}.png`, kind: 'sheet',
    frameWidth: MAP_ART.hazardSize, frameHeight: MAP_ART.hazardSize, frames: MAP_ART.hazardFrames,
    width: MAP_ART.hazardSize * MAP_ART.hazardFrames, height: MAP_ART.hazardSize
  }));
  BIOME_MECHANICS.forEach((m) => out.push({
    key: zoneKey(m), path: `${MAP_DIR}/zone-${m}.png`, kind: 'sheet',
    frameWidth: MAP_ART.zoneSize, frameHeight: MAP_ART.zoneSize, frames: MAP_ART.zoneFrames,
    width: MAP_ART.zoneSize * MAP_ART.zoneFrames, height: MAP_ART.zoneSize
  }));
  // Animated space background (one variant per stage; scripts/assets/gen-space-bg.mjs). The legacy
  // biome-<id>-far/near keys above stay loaded for compatibility (ArenaScene checks them).
  spaceAssetManifest().forEach((a) => out.push(a));
  out.push({ key: CRATE_KEY, path: `${MAP_DIR}/crate.png`, kind: 'image', width: MAP_ART.crateSize, height: MAP_ART.crateSize });
  PORTAL_SIDES.forEach((side) => out.push({
    key: portalKey(side), path: `${MAP_DIR}/portal-${side}.png`, kind: 'sheet',
    frameWidth: PORTAL_ART.size, frameHeight: PORTAL_ART.size, frames: PORTAL_ART.frames,
    width: PORTAL_ART.size * PORTAL_ART.frames, height: PORTAL_ART.size
  }));
  return out;
}

/** Queue every biome texture on the scene loader (call from BootScene.preload). */
export function preloadBiomeAssets(scene) {
  biomeAssetManifest().forEach((a) => {
    if (scene.textures && scene.textures.exists(a.key)) return;
    const url = getAssetPath(a.path);
    if (a.kind === 'sheet') scene.load.spritesheet(a.key, url, { frameWidth: a.frameWidth, frameHeight: a.frameHeight });
    else scene.load.image(a.key, url);
  });
}

/** Register looping hazard/zone animations once per game (idempotent; skips missing textures). */
export function ensureBiomeAnims(scene) {
  if (!scene || !scene.anims || !scene.textures) return;
  const make = (animKey, texKey, frames, frameRate) => {
    if (scene.anims.exists(animKey) || !scene.textures.exists(texKey)) return;
    scene.anims.create({
      key: animKey,
      frames: scene.anims.generateFrameNumbers(texKey, { start: 0, end: frames - 1 }),
      frameRate,
      repeat: -1
    });
  };
  Object.keys(HAZARD_DEFS).forEach((t) => make(hazardAnimKey(t), hazardKey(t), MAP_ART.hazardFrames, 6));
  BIOME_MECHANICS.forEach((m) => make(zoneAnimKey(m), zoneKey(m), MAP_ART.zoneFrames, 5));
  PORTAL_SIDES.forEach((side) => make(portalAnimKey(side), portalKey(side), PORTAL_ART.frames, PORTAL_ART.frameRate));
}
